import re
from dataclasses import dataclass, field
from typing import Optional

# "## [2.4.0] - 2024-05-02" or "## [Unreleased]" (no date).
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# An HTML comment that starts and ends on the same line or spans several lines.
# The body cannot contain "-->", so two comments never merge into one match.
COMMENT_LINE_END = re.compile(r"[ \t]*<!--(?:(?!-->).)*-->[ \t]*(?=\n|\Z)", re.DOTALL)
COMMENT = re.compile(r"<!--(?:(?!-->).)*-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    # Comments that end their line take the whitespace around them with them,
    # so no trailing whitespace is left behind. Other comments are removed in place.
    text = COMMENT_LINE_END.sub("", text)
    return COMMENT.sub("", text)


def parse_changelog(text):
    releases = []
    current = None
    text = strip_comments(text.replace("\r\n", "\n"))
    for line in text.split("\n"):
        heading = HEADING.match(line) if line.startswith("## ") else None
        if heading:
            current = Release(heading.group("version"), heading.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _normalize_body(lines):
    # Collapse runs of blank lines to one, and drop leading and trailing blank lines.
    body = []
    for line in lines:
        if line.strip() == "":
            if body and body[-1] == "":
                continue
            body.append("")
        else:
            body.append(line)
    while body and body[-1] == "":
        body.pop()
    while body and body[0] == "":
        body.pop(0)
    return "\n".join(body)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            header = f"# {release.version} ({release.date})" if release.date else f"# {release.version}"
            body = _normalize_body(release.body)
            if not body:
                return f"{header}\n"
            return f"{header}\n\n{body}\n"
    raise LookupError(version)

